<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('imports.view');
$type=(string)($_GET['type']??$_POST['type']??'clients');$allowed=['clients','contacts','deals','services','quotations','payments'];if(!in_array($type,$allowed,true))$type='clients';
function csv_download(string $filename,array $headers,array $rows): never{crm_security_audit('data_exported','warning','Exportación: '.$filename.' · '.count($rows).' filas');header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,$headers,';');foreach($rows as$row){$safe=[];foreach($row as$v)$safe[]=crm_safe_csv_cell($v);fputcsv($out,$safe,';');}fclose($out);exit;}
if(($_GET['action']??'')==='export'){require_permission('reports.export');switch($type){case'clients':$rows=db()->query('SELECT company_name,trade_name,tax_id,country,city,address,website,industry,status,start_date,contact_name,contact_role,email,secondary_email,phone,whatsapp,preferred_language,preferred_contact,notes FROM clients ORDER BY country,company_name')->fetchAll();csv_download('clientes-'.date('Ymd').'.csv',array_keys($rows[0]??array_fill_keys(['company_name','trade_name','tax_id','country','city','address','website','industry','status','start_date','contact_name','contact_role','email','secondary_email','phone','whatsapp','preferred_language','preferred_contact','notes'],'')),array_map('array_values',$rows));case'contacts':$rows=db()->query("SELECT c.company_name,p.first_name,p.last_name,p.job_title,p.department,p.email,p.secondary_email,p.phone,p.whatsapp,p.language,p.status,p.source,p.notes FROM contacts p LEFT JOIN clients c ON c.id=p.client_id ORDER BY p.first_name,p.last_name")->fetchAll();csv_download('contactos-'.date('Ymd').'.csv',array_keys($rows[0]??[]),array_map('array_values',$rows));case'deals':$rows=db()->query("SELECT d.title,c.company_name,CONCAT(p.first_name,' ',COALESCE(p.last_name,'')) contact,s.name_es stage,u.name owner,d.amount,d.currency,d.probability,d.expected_close_date,d.source,d.status,d.next_action,d.next_action_at,d.notes FROM deals d LEFT JOIN clients c ON c.id=d.client_id LEFT JOIN contacts p ON p.id=d.contact_id LEFT JOIN pipeline_stages s ON s.id=d.stage_id LEFT JOIN users u ON u.id=d.owner_user_id ORDER BY d.created_at DESC")->fetchAll();csv_download('negocios-'.date('Ymd').'.csv',array_keys($rows[0]??[]),array_map('array_values',$rows));case'services':$rows=db()->query("SELECT c.company_name,s.name,s.description,s.contract_type,s.start_date,s.expiration_date,s.amount,s.currency,s.payment_status,s.status FROM client_services s JOIN clients c ON c.id=s.client_id ORDER BY c.company_name,s.name")->fetchAll();csv_download('servicios-clientes-'.date('Ymd').'.csv',array_keys($rows[0]??[]),array_map('array_values',$rows));case'quotations':$rows=db()->query("SELECT q.quotation_number,c.company_name,q.recipient_name,q.recipient_email,q.language,q.currency,q.issue_date,q.valid_until,q.status,q.subtotal,q.discount_amount,q.tax_rate,q.tax_amount,q.total,u.name owner FROM quotations q JOIN clients c ON c.id=q.client_id LEFT JOIN users u ON u.id=q.owner_user_id ORDER BY q.issue_date DESC")->fetchAll();csv_download('cotizaciones-'.date('Ymd').'.csv',array_keys($rows[0]??[]),array_map('array_values',$rows));case'payments':$rows=db()->query("SELECT p.payment_date,c.company_name,p.amount,p.currency,p.payment_method,p.reference,p.notes FROM payments p JOIN clients c ON c.id=p.client_id ORDER BY p.payment_date DESC")->fetchAll();csv_download('ingresos-'.date('Ymd').'.csv',array_keys($rows[0]??[]),array_map('array_values',$rows));}}
if(($_GET['action']??'')==='template'){switch($type){case'clients':csv_download('plantilla-clientes.csv',['company_name','trade_name','tax_id','country','city','address','website','industry','status','start_date','contact_name','contact_role','email','phone','whatsapp','preferred_language'],[]);case'contacts':csv_download('plantilla-contactos.csv',['company_name','first_name','last_name','job_title','department','email','secondary_email','phone','whatsapp','language','status','source','notes'],[]);case'deals':csv_download('plantilla-negocios.csv',['title','company_name','contact_email','amount','currency','probability','expected_close_date','source','next_action','notes'],[]);default:csv_download('plantilla.csv',['campo'],[]);}}
$pageTitle='Importar y exportar';$errors=[];$summary=null;
if($_SERVER['REQUEST_METHOD']==='POST'){require_permission('imports.manage');verify_csrf();if(!isset($_FILES['csv'])||($_FILES['csv']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)$errors[]='Selecciona un archivo CSV.';if(isset($_FILES['csv'])&&($_FILES['csv']['size']??0)>10*1024*1024)$errors[]='El CSV no puede superar 10 MB.';if(!$errors){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['csv']['tmp_name']);if(!in_array($mime,['text/plain','text/csv','application/csv','application/vnd.ms-excel'],true))$errors[]='El archivo no parece ser un CSV válido.';}if(!$errors){$handle=fopen($_FILES['csv']['tmp_name'],'rb');if(!$handle)$errors[]='No fue posible leer el CSV.';else{$first=fgets($handle);rewind($handle);$delimiter=substr_count((string)$first,';')>=substr_count((string)$first,',')?';':',';$header=fgetcsv($handle,0,$delimiter);if(!$header)$errors[]='El archivo no contiene encabezados.';else{$header=array_map(fn($h)=>trim(preg_replace('/^\xEF\xBB\xBF/','',(string)$h)),$header);$created=0;$skipped=0;$failed=0;$pdo=db();while(($line=fgetcsv($handle,0,$delimiter))!==false){if(count(array_filter($line,fn($v)=>trim((string)$v)!==''))===0)continue;$data=[];foreach($header as$i=>$key)$data[$key]=trim((string)($line[$i]??''));try{if($type==='clients'){if(($data['company_name']??'')===''){$skipped++;continue;}$exists=$pdo->prepare('SELECT id FROM clients WHERE company_name=? AND COALESCE(country,\'\')=COALESCE(?,\'\') LIMIT 1');$exists->execute([$data['company_name'],$data['country']??'']);if($exists->fetchColumn()){$skipped++;continue;}$pdo->prepare("INSERT INTO clients(company_name,trade_name,tax_id,country,city,address,website,industry,status,start_date,contact_name,contact_role,email,phone,whatsapp,preferred_language,owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$data['company_name'],$data['trade_name']??null,$data['tax_id']??null,$data['country']??null,$data['city']??null,$data['address']??null,$data['website']??null,$data['industry']??null,in_array($data['status']??'active',['active','inactive','prospect'],true)?$data['status']:'active',($data['start_date']??'')?:null,$data['contact_name']??null,$data['contact_role']??null,$data['email']??null,$data['phone']??null,$data['whatsapp']??null,in_array($data['preferred_language']??'es',['es','pt','en'],true)?$data['preferred_language']:'es',(int)$_SESSION['user_id']]);$created++;}elseif($type==='contacts'){if(($data['first_name']??'')===''){$skipped++;continue;}$clientId=null;if(($data['company_name']??'')!==''){$s=$pdo->prepare('SELECT id FROM clients WHERE company_name=? LIMIT 1');$s->execute([$data['company_name']]);$clientId=$s->fetchColumn()?:null;}$pdo->prepare("INSERT INTO contacts(client_id,first_name,last_name,job_title,department,email,secondary_email,phone,whatsapp,language,status,source,notes,owner_user_id) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute([$clientId,$data['first_name'],$data['last_name']??null,$data['job_title']??null,$data['department']??null,$data['email']??null,$data['secondary_email']??null,$data['phone']??null,$data['whatsapp']??null,in_array($data['language']??'es',['es','pt','en'],true)?$data['language']:'es',in_array($data['status']??'active',['active','inactive','lead'],true)?$data['status']:'active',$data['source']??'Importación',$data['notes']??null,(int)$_SESSION['user_id']]);$created++;}elseif($type==='deals'){if(($data['title']??'')===''){$skipped++;continue;}$clientId=null;$contactId=null;if(($data['company_name']??'')!==''){$s=$pdo->prepare('SELECT id FROM clients WHERE company_name=? LIMIT 1');$s->execute([$data['company_name']]);$clientId=$s->fetchColumn()?:null;}if(($data['contact_email']??'')!==''){$s=$pdo->prepare('SELECT id FROM contacts WHERE email=? LIMIT 1');$s->execute([$data['contact_email']]);$contactId=$s->fetchColumn()?:null;}$stage=(int)$pdo->query('SELECT id FROM pipeline_stages WHERE is_active=1 ORDER BY sort_order,id LIMIT 1')->fetchColumn();if(!$stage)throw new RuntimeException('No hay etapas de pipeline.');$currency=in_array($data['currency']??'USD',['CLP','USD','BRL'],true)?$data['currency']:'USD';$prob=max(0,min(100,(int)($data['probability']??10)));$pdo->prepare("INSERT INTO deals(title,client_id,contact_id,owner_user_id,stage_id,amount,currency,probability,expected_close_date,source,status,next_action,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,'open',?,?,?)")->execute([$data['title'],$clientId,$contactId,(int)$_SESSION['user_id'],$stage,(float)($data['amount']??0),$currency,$prob,($data['expected_close_date']??'')?:null,$data['source']??'Importación',$data['next_action']??null,$data['notes']??null,(int)$_SESSION['user_id']]);$created++;}else{$skipped++;}}catch(Throwable){$failed++;}}fclose($handle);$summary=['created'=>$created,'skipped'=>$skipped,'failed'=>$failed];crm_security_audit('data_imported','warning','Importación '.$type.': '.$created.' creados, '.$skipped.' omitidos, '.$failed.' errores');}}}}
require __DIR__.'/includes/header.php';?>
<?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><?php if($summary):?><div class="alert alert-success">Importación finalizada: <?=$summary['created']?> creados, <?=$summary['skipped']?> omitidos y <?=$summary['failed']?> con error.</div><?php endif;?>
